/**
 * Registry of procedural families by name (ROADMAP A1, M1.F). The dump CLI
 * (`npm run dump:families`), the registry test and, later, the selector (M1.14) resolve
 * families here.
 *
 * Family implementers do NOT edit this file: each family lives in its own
 * `web/src/tasks/<family>/` directory and is dumped with `--module` until an integrator adds
 * it here as `[family.name]: family`. The toy `_example` family is never registered.
 *
 * Every registered family must also have an entry in `registry.test.ts` (its property options),
 * and its bank twin in `hb.gen.registry` with a `golden/ts_dumps/<name>.json` dump (A1, A17).
 *
 * Regenerating a stored item (session restore, re-scoring saved responses, R-8.1) goes through
 * {@link resolveItem}, which checks the generator version, never through
 * `getFamily(parseItemId(id).family).generate(seed)`: that silently makes a different item for a
 * bank twin id (`+py`) or an id from before a generator bump (A11).
 */

import { coding } from './coding'
import { cubenet } from './cubenet'
import type { AnyFamily, ItemInstance } from './family'
import { figure2d } from './figure2d'
import { folding } from './folding'
import { isPyTwinVersion, parseItemId } from './ids'
import { MATRICES_LEGACY_FAMILIES, matrices } from './matrices'
import { qdata } from './qdata'
import { QUANT_LEGACY_FAMILIES, quant } from './quant'
import { reading } from './reading'
import { ROTATION_LEGACY_FAMILIES, rotation } from './rotation'
import { rtChoice4, rtSimple } from './rt'
import { SERIES_LEGACY_FAMILIES, series } from './series'
import { SPAN_LEGACY_FAMILIES, corsi, spanBwd, spanFwd } from './span'
import { syllogism } from './syllogism'

/**
 * M1 procedural families (§4.2, §14.3 M1), keyed by `family.name`: item families (kind 'item')
 * rotation (M1.5), matrices (M1.6), series (M1.7) and quant (M1.8); block families (kind
 * 'block', one per sub-task, M1.F2) span_fwd, span_bwd and corsi (M1.9), rt_simple and
 * rt_choice4 (M1.10), coding (M1.11) and reading (M1.12). The scope-variety item families (M3.13): qdata (tables, charts and everyday word problems) on
 * Quantitative; figure2d (2D
 * turning and mirror images), cubenet (cube nets) and folding (paper folding) on Spatial; syllogism (formal deduction) on Logical
 * Reasoning, served only (the device version has no Logical Reasoning part).
 */
const REGISTERED: readonly AnyFamily[] = [rotation, matrices, series, quant, qdata, figure2d, cubenet, folding, syllogism, spanFwd, spanBwd, corsi, rtSimple, rtChoice4, coding, reading]

/**
 * The registered names, in registry order. Kept as a string literal on purpose: the bank's
 * `tests/gen/test_registry.py` reads it from this file to check that `hb.gen.registry` and the
 * `golden/ts_dumps/<name>.json` dumps cover the same families (A1, A17). `registry.test.ts`
 * checks it equals the keys of {@link FAMILIES}.
 */
export const FAMILY_NAMES = ['rotation', 'matrices', 'series', 'quant', 'qdata', 'figure2d', 'cubenet', 'folding', 'syllogism', 'span_fwd', 'span_bwd', 'corsi', 'rt_simple', 'rt_choice4', 'coding', 'reading'] as const

export const FAMILIES: Readonly<Record<string, AnyFamily>> = Object.freeze(Object.fromEntries(REGISTERED.map((f) => [f.name, f])))

/** The registered family called `name`, or undefined. */
export function getFamily(name: string): AnyFamily | undefined {
  return Object.hasOwn(FAMILIES, name) ? FAMILIES[name] : undefined
}

/**
 * The item `itemId` names, regenerated by this build (A11, R-8.1), or null when this build cannot
 * make THAT item: a malformed id, an unregistered family (e.g. `rt` before its 2.0.0 split), a
 * generator version other than the family's current one (older ids regenerate different
 * content), a bank Python twin id (`<ver>+py`, which no TS generator rebuilds), or a seed whose
 * `@s<k>` stratum the family cannot target. On null a caller keeps the stored `correct` (§8
 * tuple) and needs the item's params from the server or a kept payload (M1.15, M1.Q); it never
 * substitutes the current generator's item.
 */
export function resolveItem(itemId: string): ItemInstance<object, object> | null {
  const ids = typeof itemId === 'string' ? parseItemId(itemId) : null
  if (ids === null || isPyTwinVersion(ids.generatorVersion)) return null
  const family = generatorOf(ids.family, ids.generatorVersion)
  if (family === undefined) return null
  let item: ItemInstance<object, object>
  try {
    item = family.generate(ids.seed)
  } catch (e) {
    if (e instanceof RangeError) return null // the contract's error for an untargetable stratum
    throw e
  }
  return item.item_id === itemId ? item : null
}

/**
 * Earlier generators this build still carries whole, by family name and exact version: the span
 * blocks of 1.1.0 (both trials of every length; `span/index.ts` SPAN_LEGACY_FAMILIES), quant
 * 1.3.0 (strata 1–4; `quant/index.ts` QUANT_LEGACY_FAMILIES), and the versions of matrices,
 * series and rotation before their hard strata (M3.12; each family's `<FAMILY>_LEGACY_FAMILIES`).
 * They are not
 * registered, are never planned or served, and exist so that a save made before the generator
 * changed keeps its score when it is re-scored (R-8.1). Each is that version's own code path, so
 * the rule of A11 holds: an id names exactly one implementation.
 */
const LEGACY_LIST: readonly AnyFamily[] = [
  ...Object.values(SPAN_LEGACY_FAMILIES).map((f) => f as unknown as AnyFamily),
  ...Object.values(ROTATION_LEGACY_FAMILIES).map((f) => f as unknown as AnyFamily),
  // M3.12 (harder items): one line per family whose generator was bumped.
  ...Object.values(QUANT_LEGACY_FAMILIES).map((f) => f as unknown as AnyFamily),
  ...Object.values(SERIES_LEGACY_FAMILIES).map((f) => f as unknown as AnyFamily),
  ...Object.values(MATRICES_LEGACY_FAMILIES).map((f) => f as unknown as AnyFamily),
]

const LEGACY_GENERATORS: Readonly<Record<string, AnyFamily>> = Object.freeze(
  Object.fromEntries(LEGACY_LIST.map((f) => [`${f.name}@${f.generatorVersion}`, f])),
)

/**
 * The generator of exactly this version of a family: the registered family when the versions match,
 * else a kept earlier one ({@link LEGACY_GENERATORS}), else undefined. Use it, not {@link getFamily},
 * to score a response against the item {@link resolveItem} made from a saved id.
 */
export function generatorOf(name: string, generatorVersion: string): AnyFamily | undefined {
  const family = getFamily(name)
  if (family !== undefined && family.generatorVersion === generatorVersion) return family
  return LEGACY_GENERATORS[`${name}@${generatorVersion}`]
}
